*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f5f8ff;background:#06121e;font-synthesis:none}html,body{margin:0;width:100%;height:100%;overflow:hidden;touch-action:none}body{display:grid;place-items:center}.game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#071725;isolation:isolate;user-select:none;-webkit-user-select:none}.game-shell:before{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at 50% 46%,#143345 0%,#0b2231 44%,#071522 100%)}canvas{position:absolute;inset:0;width:100%;height:100%;z-index:0}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(2,9,17,.4) 100%);z-index:1}.topbar{position:absolute;left:0;right:0;top:0;padding:calc(22px + env(safe-area-inset-top)) 34px 14px;display:flex;align-items:center;justify-content:space-between;z-index:5;transition:opacity .3s}.brand{font-family:'Space Grotesk',sans-serif;letter-spacing:2.4px;font-size:13px;font-weight:700;display:flex;align-items:center;gap:9px;color:#eaf6ff}.brand-light{font-weight:500;color:#77a9b5}.brand-mark{color:#61f3d0;font-size:21px}.top-actions{display:flex;gap:9px}.icon-btn{width:39px;height:39px;border:1px solid rgba(164,222,230,.16);border-radius:50%;background:rgba(9,31,43,.52);color:#c8e5e9;font-size:17px;cursor:pointer;backdrop-filter:blur(8px);transition:.2s}.icon-btn:hover{border-color:#5ce8ce;color:#62f5d6;transform:translateY(-1px)}.hud{position:absolute;z-index:3;top:105px;left:50%;transform:translateX(-50%);width:min(600px,calc(100% - 48px));display:flex;justify-content:space-between;align-items:center;opacity:0;transition:opacity .3s;pointer-events:none}.hud.active{opacity:1}.hud-block{display:flex;flex-direction:column;gap:1px;min-width:100px}.hud-label{font-size:9px;letter-spacing:2.4px;font-weight:700;color:#80a8b2}.hud-block strong{font-family:'Space Grotesk',sans-serif;font-size:31px;letter-spacing:1px;line-height:1.1;color:white}.lives-block{align-items:flex-end}.hearts{display:flex;gap:6px;margin-top:8px}.hearts i{font-size:13px;color:#ff6b83;font-style:normal;text-shadow:0 0 12px rgba(255,81,118,.45);transition:.2s}.hearts i.lost{color:#38505c;text-shadow:none;transform:scale(.8)}.combo-readout{display:flex;align-items:center;gap:7px;opacity:0;transform:translateY(-4px) scale(.8);transition:.2s}.combo-readout.show{opacity:1;transform:translateY(0) scale(1)}.combo-num{font:700 31px 'Space Grotesk';color:#ffdc76;text-shadow:0 0 20px #ffa344}.combo-word{font-size:9px;font-weight:800;line-height:1.1;letter-spacing:1.5px;color:#ffd98e}.chain-callout{position:absolute;z-index:5;left:50%;top:31%;transform:translate(-50%,8px) scale(.8);opacity:0;pointer-events:none;font:700 13px 'Space Grotesk';letter-spacing:2px;color:#85ffe2;text-shadow:0 0 18px #3bf3ce;transition:.18s;white-space:nowrap}.chain-callout span{font-size:17px}.chain-callout b{color:#ffdc78;margin-left:5px}.chain-callout.show{opacity:1;transform:translate(-50%,0) scale(1)}.screen{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);width:min(430px,calc(100% - 40px));text-align:center;display:flex;align-items:center;flex-direction:column;transition:opacity .28s,transform .28s}.screen.hidden{opacity:0;pointer-events:none;transform:translate(-50%,-47%)}.welcome-screen{top:51%;}.eyebrow,.mini-kicker{display:flex;align-items:center;gap:11px;color:#7fe6d0;font-size:9px;letter-spacing:3.1px;font-weight:800}.eyebrow span{width:19px;height:1px;background:#48d6bf;opacity:.65}.welcome-screen h1{font:700 clamp(54px,9vw,84px)/.79 'Space Grotesk',sans-serif;letter-spacing:-5px;margin:17px 0 14px;color:#f4f8f8;text-shadow:0 5px 35px rgba(113,225,222,.13)}h1 em,h2 em{font-style:normal;color:#63e6cb}.hero-copy{font-size:13px;line-height:1.75;color:#9ebac2;margin:0}.hero-copy b{font-weight:600;color:#dcebed}.hero-fruit{height:111px;width:210px;position:relative;display:grid;place-items:center;margin:0 auto 2px}.fruit-emoji{font-size:73px;filter:drop-shadow(0 10px 24px rgba(42,218,180,.28));z-index:1;transform:rotate(-9deg)}.fruit-orbit{position:absolute;border:1px solid rgba(95,223,198,.17);border-radius:50%;width:135px;height:53px;transform:rotate(-24deg)}.orbit-two{width:168px;height:70px;transform:rotate(28deg);border-color:rgba(116,187,209,.13)}.hero-spark{position:absolute;color:#8effdf;font-size:18px;text-shadow:0 0 12px #63eccc}.spark-a{right:25px;top:23px}.spark-b{left:28px;bottom:15px;color:#ffd36d}.primary-btn{height:54px;width:min(270px,100%);border:0;border-radius:4px;background:linear-gradient(100deg,#67f0cd,#82f3c1);color:#08241f;display:flex;align-items:center;justify-content:center;gap:31px;font:800 11px 'DM Sans';letter-spacing:2px;box-shadow:0 9px 30px rgba(62,222,185,.2);cursor:pointer;transition:transform .18s,box-shadow .18s}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 12px 35px rgba(62,222,185,.33)}.primary-btn b{font-size:17px;font-weight:500}.best-line{font-size:9px;letter-spacing:2px;color:#73949d;margin-top:18px}.best-line strong{font:600 11px 'Space Grotesk';color:#d9e8e8;margin-left:7px}.howto{display:flex;align-items:center;text-align:left;gap:12px;margin-top:29px;padding-top:17px;border-top:1px solid rgba(158,205,209,.11);width:min(300px,100%)}.swipe-icon{font-size:25px;color:#72e8d1;transform:rotate(-10deg)}.howto span:last-child{display:flex;flex-direction:column;gap:3px}.howto b{font-size:9px;letter-spacing:1.5px;color:#d7e9e9}.howto small{font-size:10px;color:#789aa4}.pause-screen,.end-screen{padding:34px 25px;background:rgba(7,24,34,.84);border:1px solid rgba(139,226,217,.16);box-shadow:0 20px 90px rgba(0,0,0,.25);backdrop-filter:blur(15px);border-radius:9px}.pause-screen h2,.end-screen h2{font:700 51px/.96 'Space Grotesk';letter-spacing:-2px;margin:15px 0 7px}.pause-screen p{font-size:13px;color:#9bb8bd;margin:0 0 27px}.text-btn{border:0;background:none;color:#89a7ae;font:700 9px 'DM Sans';letter-spacing:2px;padding:17px 20px 2px;cursor:pointer}.text-btn:hover{color:white}.end-screen h2{margin-bottom:20px}.result-score{display:flex;flex-direction:column;gap:2px;margin:0 0 12px}.result-score span{font-size:9px;letter-spacing:2px;color:#87a9af}.result-score strong{font:700 44px 'Space Grotesk';color:white}.new-best{font-size:9px;color:#ffd979;letter-spacing:2px;margin:0 0 20px}.new-best.hidden{display:none}.toast{position:absolute;z-index:6;left:50%;top:39%;transform:translate(-50%,10px) scale(.8);opacity:0;color:#ffdf8b;font:800 11px 'Space Grotesk';letter-spacing:2px;text-shadow:0 0 18px #ffaa43;transition:.2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0) scale(1)}.bottom-hint{position:absolute;z-index:3;bottom:calc(23px + env(safe-area-inset-bottom));width:100%;text-align:center;color:#648691;font:700 8px 'DM Sans';letter-spacing:2.5px;transition:opacity .3s}.bottom-hint span{color:#68dfc4;margin:0 8px}.bottom-hint.dim{opacity:0}
@media(max-height:700px){.welcome-screen{top:52%}.eyebrow{font-size:8px}.welcome-screen h1{font-size:62px;margin:12px 0}.hero-fruit{height:83px}.fruit-emoji{font-size:61px}.howto{margin-top:19px;padding-top:12px}.hud{top:82px}.bottom-hint{bottom:12px}}
@media(max-width:520px){.topbar{padding-left:20px;padding-right:20px}.hud{top:86px;width:calc(100% - 42px)}.hud-block strong{font-size:26px}.hud-block{min-width:75px}.combo-num{font-size:26px}.screen{width:calc(100% - 36px)}.welcome-screen h1{font-size:66px}.hero-fruit{height:100px}.pause-screen,.end-screen{width:calc(100% - 44px)}.bottom-hint{letter-spacing:1.8px;font-size:7px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const shell = document.getElementById('gameShell');
  const $ = id => document.getElementById(id);
  const ui = {hud:$('hud'), score:$('score'), hearts:$('hearts'), combo:$('comboReadout'), comboNum:$('comboNum'), chain:$('chainCallout'), chainCount:$('chainCount'), welcome:$('welcomeScreen'), pause:$('pauseScreen'), end:$('endScreen'), best:$('bestScore'), final:$('finalScore'), newBest:$('newBest'), toast:$('toast'), bottom:$('bottomHint')};
  const fruitTypes = [
    {name:'citrus', color:'#ffb63e', light:'#ffe08a', dark:'#f18425'},
    {name:'lime', color:'#a9e85a', light:'#dcff8a', dark:'#4caf69'},
    {name:'berry', color:'#ed5872', light:'#ff9b83', dark:'#b92f66'},
    {name:'plum', color:'#a978e8', light:'#d3a9ff', dark:'#6646c0'},
    {name:'kiwi', color:'#69d49a', light:'#a9f3ae', dark:'#2b9c84'}
  ];
  let W=0,H=0,dpr=1,last=0,raf=0,mode='menu',score=0,misses=0,best=Number(localStorage.getItem('bladebound-best')||0),fruits=[],particles=[],halves=[],texts=[],trail=[],keys=[],spawnClock=0,lastSlice=-999,combo=0,swipe=null,soundOn=true,audio=null,shake=0,slowmo=0,toastTimer=0,chainTimer=0,elapsed=0;
  ui.best.textContent=String(best).padStart(4,'0');

  function resize(){const r=shell.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize); resize();
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function audioCtx(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}
  function beep(freq,duration,type='sine',volume=.035,slide=0){if(!soundOn)return;try{const a=audioCtx(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(freq,a.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),a.currentTime+duration);g.gain.setValueAtTime(volume,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+duration)}catch(_){}}
  function setMode(next){mode=next;ui.welcome.classList.toggle('hidden',next!=='menu');ui.pause.classList.toggle('hidden',next!=='paused');ui.end.classList.toggle('hidden',next!=='over');ui.hud.classList.toggle('active',next==='play'||next==='paused');ui.bottom.classList.toggle('dim',next==='play'||next==='paused');$('pauseBtn').style.display=next==='play'||next==='paused'?'block':'none';$('soundBtn').style.display=next==='menu'||next==='over'?'block':'block'}
  function startGame(){score=0;misses=0;fruits=[];particles=[];halves=[];texts=[];trail=[];combo=0;lastSlice=-999;elapsed=0;spawnClock=.35;shake=0;slowmo=0;ui.score.textContent='0000';updateHearts();ui.combo.classList.remove('show');setMode('play');beep(430,.11,'sine',.04,220);requestAnimationFrame(t=>{last=t;})}
  function updateHearts(){[...ui.hearts.children].forEach((el,i)=>el.classList.toggle('lost',i<misses))}
  function pauseGame(){if(mode==='play'){mode='paused';ui.pause.classList.remove('hidden');ui.hud.classList.add('active');}else if(mode==='paused'){mode='play';ui.pause.classList.add('hidden');last=performance.now();}}
  function endGame(){setMode('over');ui.final.textContent=String(score).padStart(4,'0');const fresh=score>best;if(fresh){best=score;localStorage.setItem('bladebound-best',best);ui.best.textContent=String(best).padStart(4,'0')}ui.newBest.classList.toggle('hidden',!fresh);$('endKicker').textContent=fresh?'PERSONAL BEST':'GOOD RUN';$('endTitle').innerHTML=fresh?'BLADE<br><em>LEGEND.</em>':'NICE<br><em>WORK.</em>';beep(180,.4,'triangle',.05,-100)}
  function spawnWave(){let count=Math.random()<.25?2:Math.floor(rand(3,5));if(elapsed>15&&Math.random()<.27)count=4;const center=rand(W*.32,W*.68),baseY=H+38;for(let i=0;i<count;i++){const isBomb=Math.random()<Math.min(.2,.07+elapsed*.002);const x=clamp(center+(i-(count-1)/2)*rand(48,66)+rand(-15,15),35,W-35);const r=rand(24,33)*(W<500?.92:1);fruits.push({x,y:baseY+rand(0,30),vx:(x-W/2)*rand(.0018,.0032)+rand(-.45,.45),vy:-rand(H*.0098,H*.0132),r,type:fruitTypes[Math.floor(Math.random()*fruitTypes.length)],bomb:isBomb,rot:rand(-.5,.5),vr:rand(-2.2,2.2),age:0,id:Math.random()})}}
  function burst(f,chain=false){const amount=chain?12:19;for(let i=0;i<amount;i++){const a=rand(0,Math.PI*2),speed=rand(chain?1:1.5,chain?4:6);particles.push({x:f.x,y:f.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:rand(.35,.8),max:.8,size:rand(2,chain?5:7),color:chain?'#71ffe2':f.type.color,kind:Math.random()<.35?'drop':'dot'})}particles.push({x:f.x,y:f.y,life:.25,max:.25,size:f.r*1.35,color:chain?'#9affea':'#fff0c1',kind:'ring'});if(!chain){halves.push({x:f.x,y:f.y,vx:f.vx-.9,vy:f.vy*.35-1.3,rot:f.rot,vr:-rand(1,3),r:f.r,type:f.type,side:-1,life:.5},{x:f.x,y:f.y,vx:f.vx+.9,vy:f.vy*.35-1.3,rot:f.rot,vr:rand(1,3),r:f.r,type:f.type,side:1,life:.5})}}
  function floatText(x,y,text,color='#e7fff8',scale=1){texts.push({x,y,text,color,life:.72,max:.72,scale})}
  function hit(f,chain=false){if(f.bomb){shake=10;slowmo=.3;for(let i=0;i<32;i++){const a=rand(0,Math.PI*2),s=rand(1,7);particles.push({x:f.x,y:f.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.4,1),max:1,size:rand(2,6),color:Math.random()<.5?'#ff785f':'#ffc56c',kind:'dot'})}beep(95,.42,'sawtooth',.08,-55);misses++;updateHearts();floatText(f.x,f.y-14,'BOMB!','#ff8a75',1.2);if(misses>=3)endGame();return false}
    burst(f,chain);score+=chain?5:10;ui.score.textContent=String(score).padStart(4,'0');if(!chain){const now=performance.now();combo=now-lastSlice<1050?combo+1:1;lastSlice=now;ui.comboNum.textContent=String(combo);ui.combo.classList.toggle('show',combo>=2);floatText(f.x,f.y-f.r*.65,combo>=3?`+10  ×${combo}`:'+10',combo>=3?'#ffe38b':'#f1fff8',combo>=3?1.12:1);beep(420+Math.min(combo,8)*70,.12,'sine',.045,250)}else{floatText(f.x,f.y,'+5 CHAIN','#88ffe4',.9)}
    return true}
  function sliceAt(x,y,px,py){let selected=[];for(let i=fruits.length-1;i>=0;i--){const f=fruits[i];if(segmentDistance(x,y,px,py,f.x,f.y)<f.r+8){selected.push(f);fruits.splice(i,1)}}if(!selected.length)return;const main=selected.find(f=>!f.bomb);for(const f of selected)hit(f,false);if(main&&mode==='play'&&combo>=3&&combo%3===0){const targets=fruits.filter(f=>!f.bomb&&Math.hypot(f.x-main.x,f.y-main.y)<190).slice(0,3);if(targets.length){for(const t of targets){fruits.splice(fruits.indexOf(t),1);hit(t,true)}ui.chainCount.textContent=`+${targets.length*5}`;ui.chain.classList.add('show');chainTimer=.7;beep(900,.2,'triangle',.04,500)}}}
  function segmentDistance(x1,y1,x2,y2,cx,cy){const dx=x2-x1,dy=y2-y1,l=dx*dx+dy*dy;if(!l)return Math.hypot(cx-x1,cy-y1);const t=clamp(((cx-x1)*dx+(cy-y1)*dy)/l,0,1);return Math.hypot(cx-(x1+t*dx),cy-(y1+t*dy))}
  function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
  canvas.addEventListener('pointerdown',e=>{if(mode!=='play')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=pointerPos(e);swipe={...p,prevX:p.x,prevY:p.y};trail.push({x:p.x,y:p.y,life:.22})});canvas.addEventListener('pointermove',e=>{if(!swipe||mode!=='play')return;e.preventDefault();const p=pointerPos(e);swipe.x=p.x;swipe.y=p.y;const d=Math.hypot(p.x-swipe.prevX,p.y-swipe.prevY);if(d>2){trail.push({x:p.x,y:p.y,life:.24});sliceAt(p.x,p.y,swipe.prevX,swipe.prevY);swipe.prevX=p.x;swipe.prevY=p.y}});function stopSwipe(){swipe=null}canvas.addEventListener('pointerup',stopSwipe);canvas.addEventListener('pointercancel',stopSwipe);
  $('startBtn').onclick=startGame;$('againBtn').onclick=startGame;$('pauseBtn').onclick=pauseGame;$('resumeBtn').onclick=pauseGame;$('quitBtn').onclick=()=>{setMode('over');ui.final.textContent=String(score).padStart(4,'0');ui.newBest.classList.add('hidden')};$('homeBtn').onclick=()=>setMode('menu');$('soundBtn').onclick=()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♫':'♪';$('soundBtn').classList.toggle('muted',!soundOn);if(soundOn)beep(500,.1)};
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='play')pauseGame()});

  function drawBackground(t){ctx.clearRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.5,H*.59,10,W*.5,H*.58,Math.max(W,H)*.65);glow.addColorStop(0,'rgba(24,74,83,.26)');glow.addColorStop(1,'rgba(3,13,22,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
    // Quiet constellation-like specks and diagonal arena lines
    ctx.save();ctx.globalAlpha=.12;ctx.strokeStyle='#4aa899';ctx.lineWidth=1;const spacing=70;for(let x=(W%spacing)/2;x<W;x+=spacing){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(H%spacing)/2;y<H;y+=spacing){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore();
    for(let i=0;i<25;i++){const x=((i*173+43)%Math.max(W,1)),y=((i*257+Math.sin(t*.0006+i)*22+H)%H);ctx.globalAlpha=.12+((Math.sin(t*.001+i)+1)*.08);ctx.fillStyle=i%4?'#a1e9d8':'#ffd78b';ctx.beginPath();ctx.arc(x,y,i%7===0?1.5:1,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
    if(mode==='play'){ctx.save();ctx.globalAlpha=.045;ctx.strokeStyle='#90ffdf';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(W/2,H+65,W*.47,150,0,Math.PI,Math.PI*2);ctx.stroke();ctx.restore()}}
  function drawFruit(f){ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.rot);const r=f.r;if(f.bomb){const g=ctx.createRadialGradient(-r*.3,-r*.4,2,0,0,r);g.addColorStop(0,'#55616a');g.addColorStop(.4,'#202c36');g.addColorStop(1,'#080e16');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r*.88,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e2a35d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(r*.3,-r*.65);ctx.quadraticCurveTo(r*.75,-r*1.25,r*.35,-r*1.45);ctx.stroke();ctx.fillStyle='#ffcb70';ctx.shadowColor='#ffad45';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(r*.35,-r*1.45,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f98769';ctx.font=`bold ${r*.53}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1);ctx.restore();return}
    const g=ctx.createRadialGradient(-r*.3,-r*.37,r*.08,0,0,r);g.addColorStop(0,f.type.light);g.addColorStop(.55,f.type.color);g.addColorStop(1,f.type.dark);ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,0,r*.88,r,0,0,Math.PI*2);ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle='rgba(255,255,255,.25)';ctx.stroke();ctx.fillStyle='rgba(255,255,255,.28)';ctx.beginPath();ctx.ellipse(-r*.29,-r*.43,r*.16,r*.28,-.45,0,Math.PI*2);ctx.fill();
    if(f.type.name==='citrus'){ctx.strokeStyle='rgba(255,245,194,.58)';ctx.lineWidth=1.3;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*4,-r*.56);ctx.quadraticCurveTo(i*7,0,i*3,r*.56);ctx.stroke()}}
    else if(f.type.name==='berry'){ctx.fillStyle='rgba(255,227,153,.65)';for(let i=0;i<8;i++){const a=i*2.4;ctx.beginPath();ctx.ellipse(Math.cos(a)*r*.52,Math.sin(a)*r*.58,1.3,2,.3,0,Math.PI*2);ctx.fill()}}
    else if(f.type.name==='kiwi'){ctx.strokeStyle='rgba(214,255,207,.5)';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(-r*.5+i*r*.24,-r*.7);ctx.lineTo(-r*.45+i*r*.24,r*.7);ctx.stroke()}}
